'use client';

import { useState, useEffect } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import { productsApi } from '@/lib/api/products';
import { useParams, useRouter } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';

export default function ProductDetailPage() {
  const t = useTranslations('product');
  const locale = useLocale();
  const params = useParams();
  const router = useRouter();

  const [product, setProduct] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    fetchProduct();
  }, [params.id]);

  const fetchProduct = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await productsApi.getProductById(params.id);
      setProduct(data);
    } catch (err) {
      setError('Failed to fetch product');
    } finally {
      setLoading(false);
    }
  };

  const getProductField = (field: string) => {
    if (!product) return '';
    const fieldName = field + (locale === 'en' ? 'En' : locale === 'zh-TW' ? 'ZhTw' : '');
    return product[fieldName] || product[field] || '';
  };

  const handleContact = () => {
    setIsModalOpen(true);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-red-600">{error}</div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-gray-600">Product not found</div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <button
        onClick={() => router.back()}
        className="mb-6 text-blue-600 hover:text-blue-800"
      >
        ← {t('back')}
      </button>

      <div className="grid md:grid-cols-2 gap-8 mb-8">
        <div>
          <div className="aspect-square relative mb-4 cursor-pointer" onClick={() => setIsModalOpen(true)}>
            {product.images && product.images.length > 0 ? (
              <Image
                src={product.images[selectedImageIndex]}
                alt={getProductField('name')}
                fill
                className="object-cover rounded-lg"
                sizes="(max-width: 768px) 100vw, 50vw"
              />
            ) : (
              <div className="w-full h-full bg-gray-200 rounded-lg flex items-center justify-center">
                <span className="text-gray-400">No image</span>
              </div>
            )}
          </div>

          {product.images && product.images.length > 1 && (
            <div className="grid grid-cols-4 gap-2">
              {product.images.map((image: string, index: number) => (
                <div
                  key={index}
                  className={`aspect-square relative cursor-pointer rounded-lg overflow-hidden ${
                    selectedImageIndex === index ? 'ring-2 ring-blue-600' : ''
                  }`}
                  onClick={() => setSelectedImageIndex(index)}
                >
                  <Image
                    src={image}
                    alt={`${getProductField('name')} ${index + 1}`}
                    fill
                    className="object-cover"
                    sizes="25vw"
                  />
                </div>
              ))}
            </div>
          )}
        </div>

        <div>
          <h1 className="text-3xl font-bold mb-4">{getProductField('name')}</h1>

          <div className="text-2xl font-bold text-blue-600 mb-6">
            ¥{product.price.toFixed(2)}
          </div>

          <div className="space-y-4 mb-6">
            {product.size && (
              <div>
                <span className="font-medium">{t('size')}:</span>
                <span className="ml-2">{product.size}</span>
              </div>
            )}
            {product.weight && (
              <div>
                <span className="font-medium">{t('weight')}:</span>
                <span className="ml-2">{product.weight}</span>
              </div>
            )}
            {product.material && (
              <div>
                <span className="font-medium">{t('material')}:</span>
                <span className="ml-2">{product.material}</span>
              </div>
            )}
            {product.master && (
              <div>
                <span className="font-medium">{t('master')}:</span>
                <span className="ml-2">{product.master}</span>
              </div>
            )}
            <div>
              <span className="font-medium">{t('category')}:</span>
              <span className="ml-2">{product.category}</span>
            </div>
          </div>

          <div className="prose max-w-none mb-6">
            <h2 className="text-xl font-semibold mb-2">Description</h2>
            <p className="text-gray-700">{getProductField('description')}</p>
          </div>

          {getProductField('story') && (
            <div className="prose max-w-none mb-6">
              <h2 className="text-xl font-semibold mb-2">{t('story')}</h2>
              <p className="text-gray-700">{getProductField('story')}</p>
            </div>
          )}

          <button
            onClick={handleContact}
            className="w-full bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700 transition-colors font-medium"
          >
            {t('contactService')}
          </button>
        </div>
      </div>

      {isModalOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4"
          onClick={() => setIsModalOpen(false)}
        >
          <div className="relative max-w-4xl w-full">
            <button
              onClick={() => setIsModalOpen(false)}
              className="absolute -top-10 right-0 text-white text-2xl"
            >
              ✕
            </button>
            {product.images && product.images.length > 0 && (
              <Image
                src={product.images[selectedImageIndex]}
                alt={getProductField('name')}
                width={1200}
                height={1200}
                className="w-full h-auto rounded-lg"
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
}
